ValidationRule.errorConditionFormula:
AND(
    /* Bypass validation for authorized rollback users */
    NOT($Permission.Zeta_Rollback_Lottery),

    TEXT(PRIORVALUE(Status)) = "Waitlisted",

    /* Only validate when the value is actually changing */
    TEXT(Status) <> TEXT(PRIORVALUE(Status)),

    /* Only enforce the specific transition being controlled */
    ISPICKVAL(Status, "Pre-Offer"),

    /* Block if lottery has NOT run */
    NOT(Has_Lottery_Run__c)
)
